/**
 * EST-090..094 — Cisco libest `estclient` against the platform.
 *
 * WHAT: a real EST client fetches the CA certificates, enrolls under raBasic (its own key) and
 * vendorMtls (a device certificate and a CSR), re-enrolls the raBasic certificate with that
 * certificate as its TLS client certificate, and has a key generated by the server. Each result is
 * read from the files estclient wrote: the right certificate, for the right key, from the RA
 * Profile's CA.
 *
 * WHY: the suite's own requests prove the protocol as the specs read it; devices run real clients,
 * and the platform must interoperate with them.
 *
 * HOW: estclient runs in Docker (`EST_ESTCLIENT_IMAGE`) with a work directory holding the edge CA
 * (`EST_EDGE_CA_CERT`) and the keys and certificates it uses; the spec skips when either is unset.
 * estclient exits 0 even when the server refuses, so each check reads its output files. The tests
 * run in order: the re-enrollment uses the raBasic certificate. Everything created is removed by
 * its run-unique common name.
 */

import { APIRequestContext, expect, test } from '@playwright/test';
import * as crypto from 'crypto';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { loadEstEnv, EstEnv } from '../../utils/estEnv';
import { getRaProfileCaFingerprints, newEstAdminContext } from '../../utils/estAdminApi';
import { certificateHasKey, cleanupCertificatesByCommonName, derToPem } from '../../utils/estEnroll';
import {
  createWorkDir,
  readEstclientCaCertificates,
  readEstclientCertificate,
  readEstclientKey,
  runEstclient,
  WORK,
} from '../../utils/estClientRunner';
import { createPolicyClient, PolicyClient } from '../../utils/estPolicyClients';
import { createCsr, KeyPair, keyToPem, sha256Fingerprint } from '../../utils/estPki';
import { privateKeyMatchesCertificate } from '../../utils/estServerKeygen';
import * as forge from 'node-forge';

test.describe.configure({ mode: 'serial' });

function hex(): string {
  return crypto.randomBytes(4).toString('hex');
}

function csrToPem(der: Buffer): string {
  const lines = der.toString('base64').match(/.{1,64}/g) as string[];
  return `-----BEGIN CERTIFICATE REQUEST-----\n${lines.join('\n')}\n-----END CERTIFICATE REQUEST-----\n`;
}

function subjectOf(der: Buffer): string {
  return new crypto.X509Certificate(der).subject;
}

test.describe('@est estclient', () => {
  let env: EstEnv;
  let api: APIRequestContext;
  let workDir: string;
  let basic: PolicyClient;
  let basicAuth: { username: string; password: string };
  /** The raBasic enrollment, re-enrolled by EST-093. */
  let enrolled: { cn: string; key: KeyPair; certificate: Buffer } | undefined;
  const undo: Array<() => Promise<unknown>> = [];

  test.beforeAll(async () => {
    env = loadEstEnv();
    test.skip(!env.estclientImage || !env.edgeCaPath, 'EST_ESTCLIENT_IMAGE and EST_EDGE_CA_CERT are not set');
    api = await newEstAdminContext(env);
    workDir = createWorkDir(os.tmpdir(), env.edgeCaPath as string);
    basic = await createPolicyClient(api, env, (step) => undo.push(step), 'raBasic', 'estclient', {
      serverKeyGeneration: true,
      renewalThreshold: 3650,
    });
    const credentials = (await basic.nextEnrollment()).credentials;
    basicAuth = credentials.basicAuth as { username: string; password: string };
  });

  test.afterAll(async () => {
    if (workDir) fs.rmSync(workDir, { recursive: true, force: true });
    if (!api) return;
    for (const step of undo.reverse()) await step();
    await api.dispose();
  });

  /** Writes a file into the work directory and returns its path inside the container. */
  function put(name: string, content: string): string {
    fs.writeFileSync(path.join(workDir, name), content, { mode: 0o600 });
    return `${WORK}/${name}`;
  }

  /** Runs estclient with output to a fresh directory and returns that directory on the host. */
  async function estclient(name: string, args: string[]): Promise<string> {
    fs.mkdirSync(path.join(workDir, name));
    const result = await runEstclient({
      image: env.estclientImage as string,
      baseUrl: env.baseUrl,
      workDir,
      args: [...args, '-o', `${WORK}/${name}`],
    });
    expect(result.code, result.output.slice(-500)).toBe(0);
    return path.join(workDir, name);
  }

  function basicArgs(): string[] {
    return ['--path-seg', basic.profile.name, '-u', basicAuth.username, '-h', basicAuth.password];
  }

  /** A run-unique common name whose certificates are removed at the end. */
  function commonName(prefix: string): string {
    const cn = `est-e2e-estclient-${prefix}-${hex()}`;
    undo.push(() => cleanupCertificatesByCommonName(api, cn));
    return cn;
  }

  test('EST-090 cacerts returns the CA certificates of the RA Profile', async () => {
    const out = await estclient('cacerts', ['-g', '--path-seg', basic.profile.name]);

    const fingerprints = readEstclientCaCertificates(out).map((der) => sha256Fingerprint(der));
    expect(fingerprints.sort()).toEqual((await getRaProfileCaFingerprints(api, env.authorityUuid, env.raProfileUuid)).sort());
  });

  test('EST-091 simpleenroll under raBasic with the client own key', async () => {
    const cn = commonName('basic');
    const key = forge.pki.rsa.generateKeyPair(2048);
    const keyFile = put('basic.key', keyToPem(key));

    const out = await estclient('basic', ['-e', ...basicArgs(), '-x', keyFile, '--common-name', cn]);

    const certificate = readEstclientCertificate(out);
    expect(subjectOf(certificate)).toBe(`CN=${cn}`);
    expect(certificateHasKey(certificate, key)).toBe(true);
    enrolled = { cn, key, certificate };
  });

  test('EST-092 simpleenroll under vendorMtls with a device certificate and a CSR', async () => {
    const vendor = await createPolicyClient(api, env, (step) => undo.push(step), 'vendorMtls', 'estclient');
    const { subject, sans, credentials } = await vendor.nextEnrollment();
    undo.push(() => cleanupCertificatesByCommonName(api, String(subject[0].value)));
    const csr = createCsr({ subject, sans });

    const out = await estclient('vendor', [
      '-e',
      '--path-seg',
      vendor.profile.name,
      '-c',
      put('device.crt', credentials.clientCert?.cert as string),
      '-k',
      put('device.key', credentials.clientCert?.key as string),
      '-y',
      put('vendor.csr', csrToPem(csr.der)),
    ]);

    const certificate = readEstclientCertificate(out);
    expect(subjectOf(certificate)).toContain(`CN=${subject[0].value}`);
    expect(certificateHasKey(certificate, csr.key)).toBe(true);
  });

  test('EST-093 simplereenroll renews the raBasic certificate with it as the client certificate', async () => {
    test.skip(!enrolled, 'EST-091 did not enroll');
    const { cn, key, certificate } = enrolled as NonNullable<typeof enrolled>;
    const keyFile = put('reenroll.key', keyToPem(key));

    const out = await estclient('reenroll', [
      '-r',
      '--path-seg',
      basic.profile.name,
      '-c',
      put('reenroll.crt', derToPem(certificate)),
      '-k',
      keyFile,
      '-x',
      keyFile,
    ]);

    const renewed = readEstclientCertificate(out);
    expect(subjectOf(renewed)).toBe(`CN=${cn}`);
    expect(certificateHasKey(renewed, key)).toBe(true);
    expect(sha256Fingerprint(renewed)).not.toBe(sha256Fingerprint(certificate));
  });

  test('EST-094 serverkeygen returns a certificate and the key that belongs to it', async () => {
    const cn = commonName('skg');
    // libest builds the request with a key of its own and needs it to be RSA.
    const keyFile = put('skg.key', keyToPem(forge.pki.rsa.generateKeyPair(2048)));

    const out = await estclient('skg', ['-q', ...basicArgs(), '-x', keyFile, '--common-name', cn]);

    const certificate = readEstclientCertificate(out);
    expect(subjectOf(certificate)).toBe(`CN=${cn}`);
    expect(privateKeyMatchesCertificate(readEstclientKey(out), certificate)).toBe(true);
  });
});
